const e=[{id:"sv-4-bb246",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:1,stem:"A $2^{6-2}$ fractional factorial on **provisioning workflow** is planned. How many runs are needed?",options:["16","64","8","32"],answer:0,hint:"Runs = 2^(k − p) × replicates + center points.",steps:[{title:"Given",body:"k = 6, p = 2, r = 1, $n_c$ = 0."},{title:"Formula",body:"$$N=2^{k-p}\\times r+n_c$$"},{title:"Compute",body:"$$N=2^{4}\\times 1+0=16\\times 1+0=16$$"},{title:"Compare",body:"The full $2^6$ would need 64 runs; the fraction uses 1 ÷ 4 of the factorial runs."}],final:"N = 16 → answer **A**",whyWrong:["","This is the full factorial size; the fraction divides it by $2^p$.","One factor too many was removed from the exponent.","Only a half fraction was assumed; p = 2 means a 1 ÷ 4 fraction."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb247",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"A $2^{7-3}$ fractional factorial on **router configuration** is planned with **2 replicates**. How many runs are needed?",options:["256","32","16","128"],answer:1,hint:"Runs = 2^(k − p) × replicates + center points.",steps:[{title:"Given",body:"k = 7, p = 3, r = 2, $n_c$ = 0."},{title:"Formula",body:"$$N=2^{k-p}\\times r+n_c$$"},{title:"Compute",body:"$$N=2^{4}\\times 2+0=16\\times 2+0=32$$"},{title:"Compare",body:"The full $2^7$ would need 256 runs; the fraction uses 1 ÷ 8 of the factorial runs."}],final:"N = 32 → answer **B**",whyWrong:["This is the full factorial size; the fraction divides it by $2^p$.","","Only one replicate of the fraction was counted, without the center points.","Only a half fraction was assumed; p = 3 means a 1 ÷ 8 fraction."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb248",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"A $2^{5-1}$ fractional factorial on **cloud autoscaling policy** is planned and **4 center points**. How many runs are needed?",options:["36","20","16","64"],answer:1,hint:"Runs = 2^(k − p) × replicates + center points.",steps:[{title:"Given",body:"k = 5, p = 1, r = 1, $n_c$ = 4."},{title:"Formula",body:"$$N=2^{k-p}\\times r+n_c$$"},{title:"Compute",body:"$$N=2^{4}\\times 1+4=16\\times 1+4=20$$"},{title:"Compare",body:"The full $2^5$ would need 36 runs; the fraction uses 1 ÷ 2 of the factorial runs."}],final:"N = 20 → answer **B**",whyWrong:["This is the full factorial size; the fraction divides it by $2^p$.","","Only one replicate of the fraction was counted, without the center points.","The center points were multiplied by the fraction size; they are simply added as extra runs."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb249",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:1,stem:"What fraction of the full factorial is a $2^{8-3}$ design, and how many runs does it have?",options:["1/4 fraction, 64 runs","1/8 fraction, 256 runs","1/32 fraction, 8 runs","1/8 fraction, 32 runs"],answer:3,hint:"A $2^{k-p}$ design is a 1 ÷ $2^p$ fraction with $2^{k-p}$ runs.",steps:[{title:"Fraction",body:"$$\\dfrac{1}{2^{3}}=\\dfrac{1}{8}$$"},{title:"Runs",body:"$$2^{8-3}=2^{5}=32$$ out of $2^8$ = 256."},{title:"Name",body:"eighth fraction."}],final:"1/8, 32 runs → answer **D**",whyWrong:["One generator too few was assumed: p generators give a 1 ÷ $2^p$ fraction.","256 is the full factorial; the fraction has 32 runs.","The exponents were swapped: the run count is $2^{k-p}$ and the fraction is 1 ÷ $2^p$.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb250",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:1,stem:"What fraction of the full factorial is a $2^{5-2}$ design, and how many runs does it have?",options:["1/2 fraction, 16 runs","1/4 fraction, 32 runs","1/4 fraction, 8 runs","1/8 fraction, 4 runs"],answer:2,hint:"A $2^{k-p}$ design is a 1 ÷ $2^p$ fraction with $2^{k-p}$ runs.",steps:[{title:"Fraction",body:"$$\\dfrac{1}{2^{2}}=\\dfrac{1}{4}$$"},{title:"Runs",body:"$$2^{5-2}=2^{3}=8$$ out of $2^5$ = 32."},{title:"Name",body:"quarter fraction."}],final:"1/4, 8 runs → answer **C**",whyWrong:["One generator too few was assumed: p generators give a 1 ÷ $2^p$ fraction.","32 is the full factorial; the fraction has 8 runs.","","The exponents were swapped: the run count is $2^{k-p}$ and the fraction is 1 ÷ $2^p$."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb251",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"A Black Belt screens **7 factors** for **billing-error rate** in **16 runs** (no replicates). What is p, the number of generators, and how is the design written?",options:["p = 3; $2^{7-3}$","p = 4; $2^{7-4}$","p = 2; $2^{7-2}$","p = 1; $2^{7-1}$"],answer:0,hint:"Solve $2^{k-p}=N$: k − p = log₂N, so p = k − log₂N.",steps:[{title:"Given",body:"k = 7, N = 16."},{title:"Base factors",body:"$$2^{k-p}=16\\Rightarrow k-p=\\log_2 16=4$$"},{title:"Generators",body:"$$p=7-4=3$$ So 3 factors are generated from interactions of the 4 base factors."},{title:"Check",body:"$$2^{4}=2\\times 2\\times 2\\times 2=16$$"}],final:"p = 3 → answer **A**",whyWrong:["","log₂N is k − p (the number of base factors), not p.","This design would need $2^{5}$ = 32 runs, not 16.","A half fraction of 7 factors needs 64 runs; the fraction must be smaller to fit in 16."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb252",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"A Black Belt screens **9 factors** for **billing-error rate** in **32 runs** (no replicates). What is p, the number of generators, and how is the design written?",options:["p = 5; $2^{9-5}$","p = 3; $2^{9-3}$","p = 1; $2^{9-1}$","p = 4; $2^{9-4}$"],answer:3,hint:"Solve $2^{k-p}=N$: k − p = log₂N, so p = k − log₂N.",steps:[{title:"Given",body:"k = 9, N = 32."},{title:"Base factors",body:"$$2^{k-p}=32\\Rightarrow k-p=\\log_2 32=5$$"},{title:"Generators",body:"$$p=9-5=4$$ So 4 factors are generated from interactions of the 5 base factors."},{title:"Check",body:"$$2^{5}=2\\times 2\\times 2\\times 2\\times 2=32$$"}],final:"p = 4 → answer **D**",whyWrong:["log₂N is k − p (the number of base factors), not p.","This design would need $2^{6}$ = 64 runs, not 32.","A half fraction of 9 factors needs 256 runs; the fraction must be smaller to fit in 32.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb253",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:1,stem:"A fractional factorial uses the generator **D = ABC**. In one run, A = +, B = −, C = −. What level is **D** set to?",options:["D = −","D = +","D = 0 (center)","D depends on the run order"],answer:1,hint:"Generated factor level = product of the signs in its generator.",steps:[{title:"Generator",body:"D = ABC: multiply the coded levels of A, B, C."},{title:"Compute",body:"$$D=(1)\\times (-1)\\times (-1)=1$$"},{title:"Set",body:"So D is run at its high level in this run."}],final:"D = + → answer **B**",whyWrong:["The signs were not multiplied correctly: count the minus signs — an even number gives +, an odd number gives −.","","A generator column is built by multiplying ±1 values, so it is always −1 or +1.","The generator fixes the level for each run; randomizing the order does not change it."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb254",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"A fractional factorial uses the generator **E = ABD**. In one run, A = −, B = +, D = −. What level is **E** set to?",options:["E = +","E = −","E = 0 (center)","E depends on the run order"],answer:0,hint:"Generated factor level = product of the signs in its generator.",steps:[{title:"Generator",body:"E = ABD: multiply the coded levels of A, B, D."},{title:"Compute",body:"$$E=(-1)\\times (1)\\times (-1)=1$$"},{title:"Set",body:"So E is run at its high level in this run."}],final:"E = + → answer **A**",whyWrong:["","The signs were not multiplied correctly: count the minus signs — an even number gives +, an odd number gives −.","A generator column is built by multiplying ±1 values, so it is always −1 or +1.","The generator fixes the level for each run; randomizing the order does not change it."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb255",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"A $2^{5-2}$ design uses the generators **D = AB and E = AC**. What is the complete defining relation?",options:["I = ABD = ACE","I = ABD = ACE = ABCDE","I = ABD = ACE = BCDE","I = AB = AC = BC"],answer:2,hint:"Turn each generator into a word (multiply both sides by the new letter), then add every product of words; squared letters cancel.",steps:[{title:"Words from generators",body:"D = AB; E = AC → I = ABD and I = ACE."},{title:"Generalized interaction",body:"$$ABD\\times ACE=BCDE$$ (letters appearing twice cancel)."},{title:"Defining relation",body:"I = ABD = ACE = BCDE."},{title:"Check",body:"A $2^{k-2}$ design has $2^2-1=3$ words besides I."}],final:"I = ABD = ACE = BCDE → answer **C**",whyWrong:["The generalized interaction (the product of the two words) is missing; with p = 2 there are $2^2-1=3$ words.","The third word must be the product of the first two, where squared letters cancel (A × A = I). Letters were combined without cancelling.","","The generated letters were left out of the words: D = AB gives the word ABD (multiply both sides by D)."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb256",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:3,stem:"A $2^{6-2}$ design uses the generators **E = ABC and F = BCD**. What is the complete defining relation?",options:["I = ABCE = BCDF","I = ABCE = ADEF = BCDF","I = ABCE = BCDF = ABCDEF","I = ABC = BCD = AD"],answer:1,hint:"Turn each generator into a word (multiply both sides by the new letter), then add every product of words; squared letters cancel.",steps:[{title:"Words from generators",body:"E = ABC; F = BCD → I = ABCE and I = BCDF."},{title:"Generalized interaction",body:"$$ABCE\\times BCDF=ADEF$$ (letters appearing twice cancel)."},{title:"Defining relation",body:"I = ABCE = ADEF = BCDF."},{title:"Check",body:"A $2^{k-2}$ design has $2^2-1=3$ words besides I."}],final:"I = ABCE = ADEF = BCDF → answer **B**",whyWrong:["The generalized interaction (the product of the two words) is missing; with p = 2 there are $2^2-1=3$ words.","","The third word must be the product of the first two, where squared letters cancel (A × A = I). Letters were combined without cancelling.","The generated letters were left out of the words: D = AB gives the word ABD (multiply both sides by D)."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb257",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:1,stem:"A $2^{7-3}$ design is built with **3 generators**. How many words (other than I) are in its complete defining relation?",options:["7","3","8","6"],answer:0,hint:"Words in the defining relation = $2^p-1$.",steps:[{title:"Given",body:"p = 3 generators."},{title:"Formula",body:"$$\\text{words}=2^p-1=2\\times 2\\times 2-1$$"},{title:"Compute",body:"$$2^3-1=7$$ (3 generators + 3 pairwise products + 1 three-way product)."}],final:"7 words → answer **A**",whyWrong:["","Only the generators were counted; their products are also words.","I itself is not counted as a word.","Only the pairwise products were added; the three-way product is a word too."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb258",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"A $2^{7-4}_{III}$ screening design (8 runs) on **contact-centre service level** is followed by a **full fold-over** (all signs reversed). How many runs are there in total, and what resolution does the combined design have?",options:["16 runs, Resolution III","8 runs, Resolution IV","16 runs, Resolution IV","24 runs, Resolution V"],answer:2,hint:"Full fold-over doubles the runs and de-aliases all main effects from two-factor interactions (III → IV).",steps:[{title:"Runs",body:"$$N=8+8=2\\times 8=16$$"},{title:"Why IV",body:"Reversing every sign flips the sign of every odd-length word in the defining relation. Combining both halves cancels the length-3 words, so the shortest remaining word has length 4."},{title:"Use",body:"Fold-over is a standard sequential step when a Resolution III screen leaves main effects ambiguous."}],final:"16 runs, Res IV → answer **C**",whyWrong:["A full fold-over of a Resolution III design gives Resolution IV: main effects become clear of two-factor interactions.","The fold-over adds another 8 runs.","","Only one block of 8 runs is added, and the result is Resolution IV."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb259",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:1,stem:"What is the **smallest two-level fractional factorial** ($2^{k-p}$ type, run size a power of 2) that can estimate the main effects of **6 factors**?",options:["6 runs","4 runs","16 runs","8 runs"],answer:3,hint:"Need $2^{k-p}-1\\ge k$, i.e. the smallest power of 2 that is at least k + 1.",steps:[{title:"Requirement",body:"$$N-1\\ge k=6\\Rightarrow N\\ge 7$$"},{title:"Smallest power of 2",body:"$$N=2^{3}=2\\times 2\\times 2=8$$ which gives 7 columns."},{title:"Design",body:"A $2^{6-3}$ design (Resolution III or higher)."}],final:"8 runs → answer **D**",whyWrong:["You need at least k + 1 runs (one df for the mean and one per main effect).","4 runs give only 3 effect columns, fewer than 6.","This works but is not the smallest.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb260",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:2,stem:"What is the **smallest two-level fractional factorial** ($2^{k-p}$ type, run size a power of 2) that can estimate the main effects of **10 factors**?",options:["10 runs","8 runs","16 runs","32 runs"],answer:2,hint:"Need $2^{k-p}-1\\ge k$, i.e. the smallest power of 2 that is at least k + 1.",steps:[{title:"Requirement",body:"$$N-1\\ge k=10\\Rightarrow N\\ge 11$$"},{title:"Smallest power of 2",body:"$$N=2^{4}=2\\times 2\\times 2\\times 2=16$$ which gives 15 columns."},{title:"Design",body:"A $2^{10-6}$ design (Resolution III or higher)."}],final:"16 runs → answer **C**",whyWrong:["You need at least k + 1 runs (one df for the mean and one per main effect).","8 runs give only 7 effect columns, fewer than 10.","","This works but is not the smallest."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb261",phase:4,topic:"4.5.1",qtype:"concept",difficulty:1,stem:"What is the main reason for using a **fractional** factorial instead of a full factorial?",options:["To estimate every interaction more precisely","To study many factors with far fewer runs, accepting that some effects will be aliased","To avoid the need for randomization","To fit quadratic models"],answer:1,hint:"Fractional factorial = economy (runs) in exchange for aliasing.",steps:[{title:"Key idea",body:"The number of full-factorial runs doubles with each factor. A fraction runs a carefully chosen subset so that the important effects (usually main effects and some two-factor interactions) can still be estimated."},{title:"Cost",body:"Some effects share a column (aliasing)."}],final:"Fewer runs, some aliasing → answer **B**",whyWrong:["A fraction estimates fewer effects and aliases the rest.","","Fractions still need randomization.","Two-level fractions cannot fit squared terms."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb262",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"Which two principles justify fractional factorial designs?",options:["Sparsity of effects and hierarchical ordering (high-order interactions are usually negligible)","Randomization and blocking","Central limit theorem and normality","Orthogonality and rotatability"],answer:0,hint:"Few effects matter, and they are usually low-order → alias the high-order ones.",steps:[{title:"Key idea",body:"If most effects are zero and high-order interactions are small, aliasing a main effect with a three-factor interaction costs little."},{title:"Consequence",body:"A well-chosen fraction estimates what matters with a fraction of the runs."}],final:"Sparsity + hierarchy → answer **A**",whyWrong:["","These are general design principles, not the reason fractions work.","These support the analysis, not the choice to fractionate.","Orthogonality is a property of fractions; rotatability belongs to RSM designs."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb263",phase:4,topic:"4.5.1",qtype:"concept",difficulty:1,stem:"In a $2^{k-p}$ design, what is a **generator**?",options:["The randomized run order produced by the software","The factor with the largest effect","The list of center points","A rule that sets the column of an added factor equal to an interaction of the base factors (e.g. D = ABC)"],answer:3,hint:"Generator: new factor = product of base-factor columns.",steps:[{title:"Key idea",body:"A $2^{4-1}$ design writes out the full $2^3$ in A, B and C, then sets D = ABC. That generator gives the word I = ABCD."},{title:"Choice",body:"Generators are chosen to give the highest possible resolution."}],final:"New factor = interaction of base factors → answer **D**",whyWrong:["Run order has nothing to do with generators.","Generators are chosen before the experiment; they say nothing about effect size.","Center points are added separately.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb264",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"What is the **principal fraction** of a $2^{k-1}$ design?",options:["The half fraction in which the generator word has a plus sign (e.g. I = +ABCD)","The half fraction with the fewest runs","The fraction that contains only center points","The first half of the runs in standard order"],answer:0,hint:"Principal fraction: I = +word; alternate (complementary) fraction: I = −word.",steps:[{title:"Key idea",body:"A $2^{4-1}$ can use D = +ABC (principal) or D = −ABC (alternate). Together they make the full $2^4$."},{title:"Use",body:"Running the alternate fraction later is a fold-over that de-aliases effects."}],final:"Generator with + sign → answer **A**",whyWrong:["","Both half fractions have the same number of runs.","Fractions are chosen from the factorial corners.","Standard order does not define a fraction."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb265",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"What does it mean that a $2^{7-4}$ design with 7 factors in 8 runs is **saturated**?",options:["It contains every possible treatment combination","It has been replicated until no more runs are possible","It has the highest possible resolution","All 7 effect columns are used by factors, so no columns are left to estimate error or interactions"],answer:3,hint:"Saturated: number of factors = N − 1.",steps:[{title:"Key idea",body:"An 8-run two-level design has 7 columns for effects. Assigning a factor to every one leaves nothing free."},{title:"Consequence",body:"Main effects are aliased with two-factor interactions; significance is judged with effects plots or by replicating."}],final:"All columns used → answer **D**",whyWrong:["That would be the full $2^7$ with 128 runs.","Saturation is about columns, not replicates.","Saturated two-level designs are Resolution III, the lowest useful resolution.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb266",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"What is the **projection property** of a Resolution III or IV fractional factorial?",options:["The design can be projected onto a larger number of factors","If only a few factors turn out to be active, the design collapses into a full factorial (possibly replicated) in those factors","The aliases disappear when the design is randomized","Effects can be predicted outside the tested range"],answer:1,hint:"A design of resolution R projects to a full factorial in any R − 1 factors.",steps:[{title:"Key idea",body:"For example, a $2^{4-1}_{IV}$ projects onto any 3 factors as a full $2^3$. A $2^{7-4}_{III}$ projects onto any 2 factors as a replicated $2^2$."},{title:"Use",body:"After screening, the data can often be reanalyzed as a full factorial in the active factors."}],final:"Collapses to a full factorial in active factors → answer **B**",whyWrong:["Projection goes to fewer factors, not more.","","Randomization does not change aliasing.","Projection has nothing to do with extrapolation."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb267",phase:4,topic:"4.5.1",qtype:"scenario",difficulty:2,stem:"A Resolution III screening study on **6 factors** for **fibre-install time** shows that factors A, C and E look active, but each main effect is aliased with two-factor interactions. What is the BEST next step?",options:["Report A, C and E as the vital few without further work","Start an RSM optimization on A, C and E at once","Run a fold-over (or a follow-up design) to de-alias the main effects from the two-factor interactions, then confirm","Repeat the same 8 runs to increase precision"],answer:2,hint:"Sequential experimentation: Res III screen → fold-over (Res IV) or augment → confirm.",steps:[{title:"Key idea",body:"In Resolution III each main effect is aliased with two-factor interactions. A full fold-over clears main effects of all two-factor interactions."},{title:"Then",body:"Characterize the confirmed vital factors with a full factorial or RSM design."}],final:"Fold-over to de-alias → answer **C**",whyWrong:["The apparent main effects could really be two-factor interactions.","Optimizing before resolving the aliasing risks optimizing the wrong factors.","","Replicating the same fraction does not break the aliasing."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb268",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"For a **half fraction** $2^{k-1}$, which generator usually gives the best design?",options:["The highest-order interaction of the base factors (e.g. E = ABCD for a $2^{5-1}$)","A main effect (e.g. E = A)","A two-factor interaction (e.g. E = AB)","Any generator; they all give the same resolution"],answer:0,hint:"Half fraction: use the longest possible word → maximum resolution (= k).",steps:[{title:"Key idea",body:"With E = ABCD the defining relation is I = ABCDE (length 5), so the design is Resolution V: main effects and two-factor interactions are clear of each other."},{title:"Contrast",body:"E = AB gives I = ABE, Resolution III."}],final:"Highest-order interaction → answer **A**",whyWrong:["","This would alias two main effects completely.","This gives only Resolution III when a higher resolution is available.","Resolution depends on the length of the generator word."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb269",phase:4,topic:"4.5.1",qtype:"not-except",difficulty:2,stem:"All of the following are sensible uses of a fractional factorial EXCEPT:",options:["Screening 9 factors in 16 runs","Studying 5 factors in 16 runs with a Resolution V design","Studying 3 factors when a full $2^3$ (8 runs) is easily affordable and interactions matter","Running a first block of a sequential study that will be folded over later"],answer:2,hint:"Use fractions when runs are expensive relative to the number of factors.",steps:[{title:"Key idea",body:"With only 3 factors, the saving from a $2^{3-1}$ (4 runs) is small and it aliases each main effect with a two-factor interaction."},{title:"Decide",body:"Run the full $2^3$ instead."}],final:"Not for 3 cheap factors → answer **C**",whyWrong:["A typical screening use.","A $2^{5-1}_V$ gives clear main effects and two-factor interactions in half the runs.","","Sequential fractions are a standard strategy."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb270",phase:4,topic:"4.5.1",qtype:"concept",difficulty:1,stem:"Minitab’s design summary says: **Factors: 6, Runs: 16, Fraction: 1/4, Resolution: IV**. Which design is this?",options:["$2^{6-4}_{IV}$","$2^{4-2}_{IV}$","$2^{6-1}_{IV}$","$2^{6-2}_{IV}$"],answer:3,hint:"Fraction 1 ÷ $2^p$; runs $2^{k-p}$; subscript = resolution.",steps:[{title:"Read",body:"k = 6; fraction 1/4 → $2^p$ = 4 → p = 2; runs $2^{6-2}$ = 16 ✓."},{title:"Write",body:"The resolution is the subscript: $2^{6-2}_{IV}$."}],final:"$2^{6-2}_{IV}$ → answer **D**",whyWrong:["A quarter fraction has p = 2, not 4.","There are 6 factors, so k = 6.","p = 1 is a half fraction with 32 runs.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb271",phase:4,topic:"4.5.1",qtype:"true-false",difficulty:1,stem:"True or false: in a regular $2^{k-p}$ fractional factorial, the main-effect columns are balanced and orthogonal to each other.",options:["True","False"],answer:0,hint:"Regular fractions keep the balance and orthogonality of the full design.",steps:[{title:"Key idea",body:"The fraction is built from a full factorial in the base factors, and generated columns are products of base columns, so balance and orthogonality are preserved."},{title:"Caveat",body:"Effects that are aliased share exactly the same column."}],final:"True → answer **True**",whyWrong:["","Regular fractions keep every column balanced and every pair of distinct columns orthogonal; aliased effects share a column."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb272",phase:4,topic:"4.5.1",qtype:"true-false",difficulty:2,stem:"True or false: a fractional factorial needs fewer confirmation runs than a full factorial because the analysis is simpler.",options:["True","False"],answer:1,hint:"More aliasing → more need to confirm.",steps:[{title:"Key idea",body:"A fraction cannot tell aliased effects apart. Confirmation runs at the predicted best settings test whether the assumed interpretation is right."},{title:"Apply",body:"Plan confirmation (and possibly fold-over) runs into the budget."}],final:"False → answer **False**",whyWrong:["Because effects are aliased, conclusions from a fraction rest on assumptions (e.g. negligible interactions), so confirmation is even more important.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb273",phase:4,topic:"4.5.1",qtype:"sequence",difficulty:2,stem:`Put these steps for building a $2^{5-1}$ design in order:

P. Write the full $2^4$ design in A, B, C, D
Q. Choose the generator E = ABCD
R. Compute the E column as the product A × B × C × D for each run
S. Randomize the run order`,options:["P → R → Q → S","Q → P → R → S","S → P → Q → R","P → Q → S → R"],answer:1,hint:"Choose generator → base design → generated column(s) → randomize.",steps:[{title:"Key idea",body:"The generator is a design decision (it fixes the resolution). Then the base factorial is written and the new column is computed run by run."},{title:"Finally",body:"Randomize the run order for execution. (P and Q can be swapped, but both come before R and S.)"}],final:"Q → P → R → S → answer **B**",whyWrong:["The E column cannot be computed before the generator is chosen.","","Randomization comes after the design matrix is complete.","The E column must be filled in before randomizing so every run has its settings."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb274",phase:4,topic:"4.5.1",qtype:"best-action",difficulty:2,stem:"A team has budget for **16 runs** and **5 factors** for **SMS gateway throughput**, and two-factor interactions are expected to matter. Which design is BEST?",options:["A $2^{5-2}_{III}$ quarter fraction in 8 runs, saving the rest","A 12-run Plackett–Burman design","A $2^{5-1}_V$ half fraction with generator E = ABCD","A $2^5$ full factorial"],answer:2,hint:"Pick the highest-resolution design that fits the budget and protects the effects you care about.",steps:[{title:"Key idea",body:"With I = ABCDE, every main effect is aliased only with a four-factor interaction and every two-factor interaction with a three-factor interaction."},{title:"Fit",body:"Exactly 16 runs, Resolution V."}],final:"$2^{5-1}_V$ → answer **C**",whyWrong:["Resolution III aliases main effects with two-factor interactions, which are expected to matter.","Plackett–Burman designs partially alias main effects with two-factor interactions.","","32 runs exceed the 16-run budget."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb275",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"Why is it useful to add **center points** to a fractional factorial screening design?",options:["They remove the aliasing between main effects and interactions","They provide a check for curvature and an estimate of pure error without changing the aliasing of the factorial effects","They increase the resolution by one","They allow squared terms to be estimated for each factor"],answer:1,hint:"Center points: curvature + pure error; no effect on aliases.",steps:[{title:"Key idea",body:"Center points are at coded 0 for every factor, so all factorial contrasts are untouched."},{title:"Benefit",body:"In a saturated screening design they may be the only source of an error estimate."}],final:"Curvature + pure error → answer **B**",whyWrong:["Center points do not change the factorial columns, so aliasing is unchanged.","","Resolution depends only on the defining relation.","Center points give only an overall curvature test."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb276",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"What is the main **risk** when interpreting a Resolution III screening design?",options:["The design cannot estimate main effects","The design always needs more runs than a full factorial","The design cannot be randomized","An apparent main effect may actually be caused by an aliased two-factor interaction"],answer:3,hint:"Resolution III: main effects aliased with 2FIs.",steps:[{title:"Key idea",body:"Each estimate is a sum, e.g. A + BC + …. If BC is large, A looks important even if it is not."},{title:"Mitigate",body:"Use process knowledge, fold-over runs and confirmation."}],final:"Main effect may be an interaction → answer **D**",whyWrong:["It can estimate main effects, but they are aliased with two-factor interactions.","It needs far fewer runs.","It can and should be randomized.",""],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb277",phase:4,topic:"4.5.1",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “Running the complementary half fraction (all generator signs reversed) after a first fraction, to break aliases, is called a [?].”",options:["fold-over","replicate","block","projection"],answer:0,hint:"Fold-over = run the mirror-image fraction to de-alias.",steps:[{title:"Key idea",body:"Combining a fraction with its fold-over removes some (or all) of the alias chains from the first fraction."},{title:"Example",body:"A full fold-over of a Resolution III design gives Resolution IV."}],final:"Fold-over → answer **A**",whyWrong:["","A replicate repeats the same runs; it does not change aliasing.","Each fraction can be a block, but the technique is called fold-over.","Projection describes collapsing a design onto fewer factors."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb278",phase:4,topic:"4.5.1",qtype:"concept",difficulty:2,stem:"How does a regular $2^{k-p}$ design differ from a **Plackett–Burman** design?",options:["In a $2^{k-p}$ design each effect is fully aliased with specific others; in a Plackett–Burman design (non-power-of-2 sizes) interactions are partially aliased with many main effects","Plackett–Burman designs always have more runs","$2^{k-p}$ designs cannot be used for screening","Plackett–Burman designs estimate all two-factor interactions"],answer:0,hint:"Regular fraction: complete aliasing in chains. PB (12, 20, 24…): partial aliasing spread across columns.",steps:[{title:"Key idea",body:"A $2^{k-p}$ design has a defining relation; every effect belongs to an alias chain. Plackett–Burman designs of size 12, 20 or 28 have no defining relation; each two-factor interaction is spread over many main-effect columns with smaller weights."},{title:"Use",body:"Both are screening tools; PB offers more run-size choices."}],final:"Complete vs partial aliasing → answer **A**",whyWrong:["","They often have fewer, e.g. 12 runs for 11 factors.","They are widely used for screening.","They are for main effects only."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb279",phase:4,topic:"4.5.1",qtype:"output",difficulty:2,stem:`Minitab shows this summary for a screening design on **5G cell-edge throughput**:

\`\`\`
Fractional Factorial Design

Factors:   6   Base Design:   4, 16   Resolution:  IV
Runs:     16   Replicates:        1   Fraction:   1/4
Blocks:    1   Center pts (total): 0

Design Generators: E = ABC, F = BCD
\`\`\`

Which statement is correct?`,options:["All six factors form a full $2^6$ factorial run in 16 blocks","A, B, C and D form a full $2^4$ base design; E and F are set from interactions of the base factors, giving a quarter fraction of the $2^6$","E and F are aliased with each other, so their effects cannot be separated","The design is Resolution IV, so two-factor interactions are clear of each other"],answer:1,hint:"Base design = full factorial in k − p factors; generators define the added factors; Fraction = 1 ÷ $2^p$.",steps:[{title:"Read",body:"k = 6, 16 runs, fraction 1/4 → p = 2. Base design: 4 factors in 16 runs."},{title:"Generators",body:"E = ABC → I = ABCE; F = BCD → I = BCDF; product ADEF. Defining relation: I = ABCE = ADEF = BCDF."},{title:"Resolution",body:"The shortest word has 4 letters → Resolution IV: main effects are clear of two-factor interactions, but two-factor interactions are aliased in pairs or triples."}],final:"Base $2^4$ + generated E, F → answer **B**",whyWrong:["A full $2^6$ needs 64 runs; this design has 16 runs and 1 block.","","E and F are not aliased with each other: their product EF appears in the word ADEF, so EF is aliased with AD, not E with F.","In Resolution IV two-factor interactions are aliased with other two-factor interactions; only main effects are clear of them."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb280",phase:4,topic:"4.5.1",qtype:"calculation",difficulty:1,stem:"Each run of a **network-slicing** experiment takes **2 hours** of lab time. How many lab hours does a $2^{6-2}$ design save compared with the full $2^6$?",options:["32 hours","128 hours","96 hours","64 hours"],answer:2,hint:"Saving = (full runs − fraction runs) × time per run.",steps:[{title:"Runs",body:"$$2^6=64\\qquad 2^{6-2}=16$$"},{title:"Saving",body:"$$(64-16)\\times 2=48\\times 2=96\\text{ h}$$"}],final:"96 hours saved → answer **C**",whyWrong:["This is the time the fraction uses, not the time it saves.","This is the time the full factorial would take.","","This is the saving of a half fraction ($2^{6-1}$), not a quarter fraction."],bookRef:"Syllabus 4.5.1"},{id:"sv-4-bb281",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:1,stem:"A $2^{4-1}$ design on **VPN tunnel set-up time** has the defining relation **I = ABCD**. What is the complete alias set of **A**?",options:["A = ABCD","A = BC","A = CD","A = BCD"],answer:3,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABCD."},{title:"Multiply",body:"$$A\\times ABCD=BCD$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"A = BCD: the estimate labelled A is really A + BCD."}],final:"A = BCD → answer **D**",whyWrong:["Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","A letter was dropped: A × ABCD = BCD keeps all three remaining letters.","CD is the alias of AB, not of A.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb282",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:1,stem:"A $2^{4-1}$ design on **call-transfer rate** has the defining relation **I = ABCD**. What is the complete alias set of **AB**?",options:["AB = ABCD","AB = BCD","AB = CD","AB = C"],answer:2,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABCD."},{title:"Multiply",body:"$$AB\\times ABCD=CD$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"AB = CD: the estimate labelled AB is really AB + CD."}],final:"AB = CD → answer **C**",whyWrong:["Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","Only A was cancelled; B appears twice as well and also cancels.","","A letter was dropped: AB × ABCD = CD."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb283",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:1,stem:"A $2^{3-1}$ design on **IPTV start-up delay** has the defining relation **I = ABC**. What is the complete alias set of **B**?",options:["B = ABC","B = AC","B = C","B = AB"],answer:1,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABC."},{title:"Multiply",body:"$$B\\times ABC=AC$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"B = AC: the estimate labelled B is really B + AC."}],final:"B = AC → answer **B**",whyWrong:["Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","","A letter was dropped: B × ABC = AC.","B was not cancelled and C was lost: B × ABC = A·B²·C = AC."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb284",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:2,stem:"A $2^{5-1}$ design on **fibre-splice loss** has the defining relation **I = ABCDE**. What is the complete alias set of **AB**?",options:["AB = ABCDE","AB = BCDE","AB = CD","AB = CDE"],answer:3,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABCDE."},{title:"Multiply",body:"$$AB\\times ABCDE=CDE$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"AB = CDE: the estimate labelled AB is really AB + CDE."}],final:"AB = CDE → answer **D**",whyWrong:["Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","Only A was cancelled; B also appears twice and cancels.","A letter was dropped: AB × ABCDE = CDE.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb285",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:2,stem:"A $2^{5-2}$ design on **order fallout rate** has the defining relation **I = ABD = ACE = BCDE**. What is the complete alias set of **A**?",options:["A = BD = CE = ABCDE","A = ABD = ACE = ABCDE","A = BD","A = BD = CE"],answer:0,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABD = ACE = BCDE."},{title:"Multiply",body:"$$A\\times ABD=BD\\quad A\\times ACE=CE\\quad A\\times BCDE=ABCDE$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"A = BD = CE = ABCDE: the estimate labelled A is really A + BD + CE + ABCDE."}],final:"A = BD = CE = ABCDE → answer **A**",whyWrong:["","Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","Only the first generator word was used; every word of the defining relation, including products of generators, gives an alias.","The generalized interaction (the product of the generator words) was forgotten, so one alias is missing."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb286",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:3,stem:"A $2^{5-2}$ design on **ticket reopen rate** has the defining relation **I = ABD = ACE = BCDE**. What is the complete alias set of **BC**?",options:["BC = ABCD = ABCE = BCDE","BC = DE = ABE = ACD","BC = ACD","BC = ABE = ACD"],answer:1,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABD = ACE = BCDE."},{title:"Multiply",body:"$$BC\\times ABD=ACD\\quad BC\\times ACE=ABE\\quad BC\\times BCDE=DE$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"BC = DE = ABE = ACD: the estimate labelled BC is really BC + DE + ABE + ACD."}],final:"BC = DE = ABE = ACD → answer **B**",whyWrong:["Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","","Only the first generator word was used; every word of the defining relation, including products of generators, gives an alias.","The generalized interaction (the product of the generator words) was forgotten, so one alias is missing."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb287",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:3,stem:"A $2^{6-2}$ design on **data-centre PUE** has the defining relation **I = ABCE = ADEF = BCDF**. What is the complete alias set of **AB**?",options:["AB = ABCE = ABCDF = ABDEF","AB = CE","AB = CE = ACDF","AB = CE = ACDF = BDEF"],answer:3,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABCE = ADEF = BCDF."},{title:"Multiply",body:"$$AB\\times ABCE=CE\\quad AB\\times ADEF=BDEF\\quad AB\\times BCDF=ACDF$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"AB = CE = ACDF = BDEF: the estimate labelled AB is really AB + CE + ACDF + BDEF."}],final:"AB = CE = ACDF = BDEF → answer **D**",whyWrong:["Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","Only the first generator word was used; every word of the defining relation, including products of generators, gives an alias.","The generalized interaction (the product of the generator words) was forgotten, so one alias is missing.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb288",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:2,stem:"A $2^{6-2}$ design on **cloud VM boot time** has the defining relation **I = ABCE = ADEF = BCDF**. What is the complete alias set of **E**?",options:["E = ABC = ADF = BCDEF","E = ABCE = ADEF = BCDEF","E = ABC","E = ABC = BCDEF"],answer:0,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABCE = ADEF = BCDF."},{title:"Multiply",body:"$$E\\times ABCE=ABC\\quad E\\times ADEF=ADF\\quad E\\times BCDF=BCDEF$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"E = ABC = ADF = BCDEF: the estimate labelled E is really E + ABC + ADF + BCDEF."}],final:"E = ABC = ADF = BCDEF → answer **A**",whyWrong:["","Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","Only the first generator word was used; every word of the defining relation, including products of generators, gives an alias.","The generalized interaction (the product of the generator words) was forgotten, so one alias is missing."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb289",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:1,stem:"In a regular $2^{7-3}$ design, how many **other** effects is each effect aliased with?",options:["3","8","7","15"],answer:2,hint:"Each effect has $2^p-1$ aliases (one per word in the defining relation).",steps:[{title:"Words",body:"$$2^p-1=2^3-1=7$$ words in the defining relation."},{title:"Aliases",body:"Multiplying an effect by each word gives one alias per word → 7 aliases."},{title:"Check",body:"$$2^{4}\\times 2^{3}=2^{7}$$ All 128 effects (counting I) fall into 16 chains of 8."}],final:"7 aliases → answer **C**",whyWrong:["Only the generators were counted; their products are also words in the defining relation.","The effect itself was counted as one of its own aliases.","","This is the number of estimable effect columns, not the number of aliases per effect."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb290",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:1,stem:"In a regular $2^{6-2}$ design, how many **other** effects is each effect aliased with?",options:["2","4","3","15"],answer:2,hint:"Each effect has $2^p-1$ aliases (one per word in the defining relation).",steps:[{title:"Words",body:"$$2^p-1=2^2-1=3$$ words in the defining relation."},{title:"Aliases",body:"Multiplying an effect by each word gives one alias per word → 3 aliases."},{title:"Check",body:"$$2^{4}\\times 2^{2}=2^{6}$$ All 64 effects (counting I) fall into 16 chains of 4."}],final:"3 aliases → answer **C**",whyWrong:["Only the generators were counted; their products are also words in the defining relation.","The effect itself was counted as one of its own aliases.","","This is the number of estimable effect columns, not the number of aliases per effect."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb291",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:2,stem:"A $2^{3-1}$ design (I = +ABC) on **chat wait time** estimated $\\ell_A$ = **8.4**, which is A + BC. The alternate fraction (I = −ABC) was then run and gave $\\ell'_A$ = **5**, which is A − BC. What are the de-aliased estimates of A and BC?",options:["A = 1.7, BC = 6.7","A = 13.4, BC = 3.4","A = 8.4, BC = 5","A = 6.7, BC = 1.7"],answer:3,hint:"With ℓ = A + BC and ℓ′ = A − BC: A = (ℓ + ℓ′) ÷ 2 and BC = (ℓ − ℓ′) ÷ 2.",steps:[{title:"Set up",body:"$$\\ell=A+BC=8.4\\qquad \\ell'=A-BC=5$$"},{title:"Main effect",body:"$$A=\\dfrac{\\ell+\\ell'}{2}=\\dfrac{8.4+(5)}{2}=6.7$$"},{title:"Interaction",body:"$$BC=\\dfrac{\\ell-\\ell'}{2}=\\dfrac{8.4-(5)}{2}=1.7$$"},{title:"Meaning",body:"Together the two half fractions form the full $2^3$, so main effects and interactions are no longer aliased."}],final:"A = 6.7, BC = 1.7 → answer **D**",whyWrong:["The sum and the difference were swapped: the sum isolates the main effect, the difference isolates the interaction.","The sum and difference were not divided by 2.","Each fraction’s estimate is still a combination; they must be added and subtracted to separate A and BC.",""],trap:"The fold-over combines two aliased estimates by adding and subtracting them.",bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb292",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:3,stem:"A $2^{3-1}$ design (I = +ABC) on **chat wait time** estimated $\\ell_C$ = **−3.6**, which is C + AB. The alternate fraction (I = −ABC) was then run and gave $\\ell'_C$ = **1.2**, which is C − AB. What are the de-aliased estimates of C and AB?",options:["C = −1.2, AB = −2.4","C = −2.4, AB = −1.2","C = −2.4, AB = −4.8","C = −3.6, AB = 1.2"],answer:0,hint:"With ℓ = A + BC and ℓ′ = A − BC: A = (ℓ + ℓ′) ÷ 2 and BC = (ℓ − ℓ′) ÷ 2.",steps:[{title:"Set up",body:"$$\\ell=C+AB=-3.6\\qquad \\ell'=C-AB=1.2$$"},{title:"Main effect",body:"$$C=\\dfrac{\\ell+\\ell'}{2}=\\dfrac{-3.6+(1.2)}{2}=-1.2$$"},{title:"Interaction",body:"$$AB=\\dfrac{\\ell-\\ell'}{2}=\\dfrac{-3.6-(1.2)}{2}=-2.4$$"},{title:"Meaning",body:"Together the two half fractions form the full $2^3$, so main effects and interactions are no longer aliased."}],final:"C = −1.2, AB = −2.4 → answer **A**",whyWrong:["","The sum and the difference were swapped: the sum isolates the main effect, the difference isolates the interaction.","The sum and difference were not divided by 2.","Each fraction’s estimate is still a combination; they must be added and subtracted to separate A and BC."],trap:"The fold-over combines two aliased estimates by adding and subtracting them.",bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb293",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:2,stem:"A $2^3$ experiment on **router CPU load** must run in **2 blocks** (two days), with **ABC** confounded with blocks. Which runs go into the block where ABC = +1?",options:["(1), ab, ac, bc","a, b, c, abc","(1), a, b, ab","a, ab, ac, abc"],answer:1,hint:"For each run, ABC sign = product of A, B, C signs. Runs with an odd number of high factors have ABC = +1.",steps:[{title:"Rule",body:"$$ABC=A\\times B\\times C$$ e.g. for run a: $(+1)\\times(-1)\\times(-1)=+1$."},{title:"Sort",body:"ABC = +1: a, b, c, abc (odd number of letters). ABC = −1: (1), ab, ac, bc."},{title:"Consequence",body:"The ABC interaction is confounded with the day effect and cannot be estimated, but all main effects and two-factor interactions remain clear."}],final:"Block 1: a, b, c, abc → answer **B**",whyWrong:["These are the runs with ABC = −1 (an even number of letters).","","This splits on C, which would confound the main effect C with the blocks.","This is the A = +1 half; it would confound A with the blocks."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb294",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:2,stem:"In a $2^{4-1}$ design with I = ABCD, the column labelled AB gives an estimate of **4.2 s** for **SMS delivery time**. Process experts say the CD interaction is impossible (C and D act on separate systems). What can be concluded?",options:["AB = 2.1 s and CD = 2.1 s, because the estimate is shared equally","AB cannot be estimated at all in a $2^{4-1}$ design","The 4.2 s estimates AB + CD; if CD ≈ 0, then AB ≈ 4.2 s","The 4.2 s is the effect of CD only, because CD comes second in the chain"],answer:2,hint:"Aliased estimate = sum of all effects in the chain; use knowledge to attribute it.",steps:[{title:"Alias",body:"$$AB\\times ABCD=A^2B^2CD=CD\\ \\Rightarrow\\ \\hat\\ell_{AB}=AB+CD$$"},{title:"Assume",body:"If CD is physically impossible, CD ≈ 0, so the whole estimate is attributed to AB."},{title:"Caution",body:"This is an assumption; a fold-over or confirmation runs can verify it."}],final:"AB ≈ 4.2 s (assuming CD ≈ 0) → answer **C**",whyWrong:["The estimate is a sum, not split equally; the split depends on the true effects.","It can be estimated as part of the AB + CD chain.","","Order in the chain has no meaning; the estimate is the sum."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb295",phase:4,topic:"4.5.2",qtype:"output",difficulty:2,stem:`Minitab prints this alias structure for a screening design on **broadband activation time**:

\`\`\`
Alias Structure

Factors: 5   Runs: 8   Generators: D = AB, E = AC

I + ABD + ACE + BCDE

A + BD + CE + ABCDE
B + AD + CDE + ABCE
C + AE + BDE + ABCD
D + AB + BCE + ACDE
E + AC + BCD + ABDE
BC + DE + ABE + ACD
BE + CD + ABC + ADE
\`\`\`

The **D** column shows a large, significant effect. Which statement is correct?`,options:["The D estimate is the sum D + AB + BCE + ACDE, so it could be caused by D or by the AB interaction","D is proven to be the active factor because main effects are listed first","The effect must be AB because two-factor interactions are larger than main effects","D is aliased only with three- and four-factor interactions, so it is clear"],answer:0,hint:"Read the whole alias chain on the line of the effect; Resolution III → main effects share a column with 2FIs.",steps:[{title:"Find the line",body:"D + AB + BCE + ACDE."},{title:"Interpret",body:"The significant column could be D, AB, or a mix. Three- and four-factor terms are usually ignored, but AB cannot be ruled out."},{title:"Next",body:"Check whether A and B are also active (heredity suggests AB is more plausible if they are), and use a fold-over on D or on all factors to separate them."}],final:"D + AB are confounded → answer **A**",whyWrong:["","The listing order is a convention; the estimate is the sum of the whole chain.","Hierarchical ordering says main effects are usually larger, not smaller.","D is aliased with the two-factor interaction AB."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb296",phase:4,topic:"4.5.2",qtype:"output",difficulty:3,stem:`A $2^{5-1}$ design for **API gateway latency** was built with generator E = ABC (16 runs). Minitab shows the alias structure up to order 2:

\`\`\`
Alias Structure (up to order 2)

I
A
B
C
D
E
AB + CE
AC + BE
AD
AE + BC
BD
CD
DE
\`\`\`

The **AB + CE** term is significant. What is the BEST interpretation?`,options:["AB is active, because it is listed first","Either AB or CE (or both) is active; use process knowledge and the heredity principle (which main effects are active) to decide, or run follow-up runs to separate them","Neither is active, because aliased terms cancel out","The design is Resolution V, so AB and CE are clear of each other"],answer:1,hint:"Resolution IV: main effects clear; some 2FIs aliased with each other → use heredity/knowledge or follow-up.",steps:[{title:"Defining relation",body:"E = ABC → I = ABCE (length 4 → Resolution IV)."},{title:"Alias pair",body:"$$AB\\times ABCE=CE$$ so the AB column also estimates CE."},{title:"Decide",body:"If A and B are significant main effects but C and E are not, AB is the more likely explanation (heredity). Confirm with a fold-over on one factor or with a few targeted runs."},{title:"Design lesson",body:"E = ABCD would have given I = ABCDE, Resolution V, with every two-factor interaction clear."}],final:"AB or CE — resolve with heredity or follow-up → answer **B**",whyWrong:["The order in the alias chain does not show which effect is real.","","Aliased effects add together; they do not cancel.","With I = ABCE the design is Resolution IV; some two-factor interactions are aliased in pairs."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb297",phase:4,topic:"4.5.2",qtype:"output",difficulty:2,stem:`Minitab gives this alias structure for an 8-run design on **voicemail retrieval time**:

\`\`\`
Alias Structure

Factors: 4   Runs: 8   Generator: D = ABC

I + ABCD

A + BCD
B + ACD
C + ABD
D + ABC
AB + CD
AC + BD
AD + BC
\`\`\`

Which statement is correct?`,options:["All main effects and two-factor interactions are estimated free of each other","Main effects are aliased with two-factor interactions","The design cannot estimate main effects because it has only 8 runs","Main effects are aliased only with three-factor interactions, but each two-factor interaction is aliased with another two-factor interaction"],answer:3,hint:"I = ABCD (4 letters) → Resolution IV.",steps:[{title:"Main effects",body:"A + BCD, B + ACD, C + ABD, D + ABC: clear of two-factor interactions if three-factor interactions are negligible."},{title:"Two-factor interactions",body:"AB + CD, AC + BD, AD + BC: aliased in pairs."},{title:"Conclusion",body:"This is the classic Resolution IV pattern."}],final:"Mains clear, 2FIs paired → answer **D**",whyWrong:["AB is aliased with CD, AC with BD, and AD with BC.","Each main effect is aliased with a three-factor interaction (e.g. A + BCD).","All four main effects are estimable (aliased only with three-factor interactions).",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb298",phase:4,topic:"4.5.2",qtype:"concept",difficulty:1,stem:"In a fractional factorial, what does it mean that two effects are **aliased** (confounded)?",options:["They have identical (or exactly opposite) columns, so the design cannot separate them; the estimate is their sum","They have the same effect size in the process","One of them has been removed from the model","They interact strongly"],answer:0,hint:"Aliased = same contrast column → combined estimate.",steps:[{title:"Key idea",body:"Because fewer runs are made, several effects share a column. The calculated “effect” for that column is the sum (or difference) of all effects in the alias chain."},{title:"Consequence",body:"Assumptions (e.g. negligible high-order interactions) are needed to attribute the estimate."}],final:"Same column, combined estimate → answer **A**",whyWrong:["","Aliasing is a property of the design columns, not of the true effect sizes.","Both are still present; they are mixed in one estimate.","Interaction is about the process; aliasing is about the design."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb299",phase:4,topic:"4.5.2",qtype:"concept",difficulty:2,stem:"What is the **defining relation** of a fractional factorial?",options:["The list of factor levels for each run","The regression equation fitted to the data","The list of words equal to the identity column I (e.g. I = ABCD), from which every alias can be found","The order in which runs are performed"],answer:2,hint:"Generators → words → I = word1 = word2 = …; alias(X) = X × word.",steps:[{title:"Key idea",body:"Each generator (e.g. D = ABC) becomes a word (I = ABCD) by multiplying both sides by the new letter. All products of words are also words."},{title:"Use",body:"Multiplying any effect by each word gives its aliases, and the shortest word gives the resolution."}],final:"Words equal to I → answer **C**",whyWrong:["That is the design matrix.","That is the model, not the defining relation.","","That is the run order."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb300",phase:4,topic:"4.5.2",qtype:"concept",difficulty:2,stem:"Why do analysts usually **assume** that the three-factor interactions in an alias chain such as A + BCD are negligible?",options:["Because three-factor interactions cannot exist in real processes","Because Minitab removes them automatically","Because they are always aliased with the constant","Because of the sparsity-of-effects and hierarchical-ordering principles — high-order interactions are rarely large"],answer:3,hint:"Attribute an aliased estimate to its lowest-order member — but it remains an assumption.",steps:[{title:"Key idea",body:"Experience shows most systems are driven by main effects and a few two-factor interactions."},{title:"Caution",body:"If process knowledge suggests a three-factor interaction, design for higher resolution or verify with follow-up runs."}],final:"Sparsity and hierarchy → answer **D**",whyWrong:["They can exist; they are just unusual.","Minitab shows them in the alias structure; the assumption is the analyst’s.","They are aliased with main effects in this case, not with the constant.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb301",phase:4,topic:"4.5.2",qtype:"concept",difficulty:2,stem:"When a $2^k$ experiment is run in **blocks**, which effects are usually chosen to be **confounded with blocks**?",options:["The main effects, because they are easiest to estimate","High-order interactions (e.g. ABC or ABCD) that are expected to be negligible","The two-factor interactions, because they are usually zero","Any effects; it makes no difference"],answer:1,hint:"Sacrifice the least important information to the blocks.",steps:[{title:"Key idea",body:"The block difference and the confounded effect share a column. Choose an effect that is probably zero."},{title:"Example",body:"A $2^3$ in two blocks confounds ABC: a, b, c, abc in one block; (1), ab, ac, bc in the other."}],final:"High-order interactions → answer **B**",whyWrong:["Confounding a main effect with blocks would lose the most important information.","","Two-factor interactions are often important.","Whatever is confounded with blocks cannot be separated from the block difference."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb302",phase:4,topic:"4.5.2",qtype:"scenario",difficulty:2,stem:"An engineer runs an unrandomized experiment on **API latency**: all runs with **cache size high** were made in the evening, and all with **cache size low** in the morning. Evening traffic is lighter. What has happened?",options:["Nothing; the design is still a valid full factorial","Cache size is confounded with time of day (traffic), so its effect cannot be separated from the traffic difference","The cache-size effect is aliased with a three-factor interaction","The traffic difference cancels because it affects all runs"],answer:1,hint:"Confounding can also occur with lurking variables through poor run order.",steps:[{title:"Key idea",body:"When a factor changes only together with an outside variable (time, operator, site), the two are confounded."},{title:"Fix",body:"Randomize the run order, or block by time of day with a balanced set of runs in each block."}],final:"Confounded with time of day → answer **B**",whyWrong:["The factors are fine, but cache size now shares a column with a lurking variable.","","The problem is confounding with an outside variable, not aliasing within the design.","It affects high and low cache runs differently, so it does not cancel."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb303",phase:4,topic:"4.5.2",qtype:"best-action",difficulty:2,stem:"When assigning factors to the columns of a $2^{5-2}$ design for **contact-centre handle time**, the team strongly suspects that **agent tenure × script version** interact. What is the BEST approach?",options:["Assign the factors so that the suspected interaction is not aliased with any main effect of interest (or choose a higher-resolution design)","Assign factors to columns at random; aliasing cannot be controlled","Put tenure and script in the generated columns so they are estimated more precisely","Ignore the suspected interaction; screening designs assume none"],answer:0,hint:"Use the alias structure to protect known likely interactions.",steps:[{title:"Key idea",body:"In a Resolution III design some two-factor interactions are aliased with main effects. Check the alias table and choose an assignment where the likely interaction falls in a chain without important main effects."},{title:"Alternative",body:"If that is impossible, use more runs (e.g. a $2^{5-1}_V$)."}],final:"Protect the suspected interaction → answer **A**",whyWrong:["","Aliasing is fixed by the generators, so the assignment can be chosen deliberately.","Generated columns are not more precise; what matters is what they are aliased with.","Known likely interactions should shape the assignment."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb304",phase:4,topic:"4.5.2",qtype:"not-except",difficulty:2,stem:"All of the following can help separate aliased effects after a fractional factorial EXCEPT:",options:["Running the fold-over fraction","Adding a few carefully chosen runs (design augmentation)","Replicating the same fraction several times","Using process knowledge and the heredity principle"],answer:2,hint:"Replicates improve precision but keep the same alias structure.",steps:[{title:"Key idea",body:"Replicating the same runs repeats the same columns, so aliased effects stay aliased."},{title:"What works",body:"New runs with different sign patterns (fold-over, augmentation) or credible assumptions."}],final:"Replication does not de-alias → answer **C**",whyWrong:["A fold-over changes the signs of the alias chains so they can be separated.","Augmentation breaks specific alias chains.","","Knowledge can justify attributing an estimate to one member of a chain."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb305",phase:4,topic:"4.5.2",qtype:"true-false",difficulty:1,stem:"True or false: in a $2^{4-1}$ design with I = ABCD, the estimate labelled A also contains the BCD interaction.",options:["True","False"],answer:0,hint:"Alias = effect × word.",steps:[{title:"Compute",body:"$$A\\times ABCD=A^2BCD=BCD$$"},{title:"Meaning",body:"The A column estimates A + BCD. Usually BCD is assumed negligible."}],final:"True → answer **True**",whyWrong:["","A × ABCD = BCD, so A and BCD share a column."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb306",phase:4,topic:"4.5.2",qtype:"true-false",difficulty:2,stem:"True or false: in a $2^{3-1}$ design with I = ABC, the main effect of C can be separated from the AB interaction by fitting both terms in the model.",options:["True","False"],answer:1,hint:"Aliased terms cannot be fitted together.",steps:[{title:"Alias",body:"$$C\\times ABC=AB$$ The C and AB columns are identical."},{title:"Consequence",body:"Software keeps only one of them (or reports it as aliased). New runs (e.g. the other half fraction) are needed to separate them."}],final:"False → answer **False**",whyWrong:["C and AB have identical columns, so including both terms gives a perfectly collinear model; their effects cannot be separated.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb307",phase:4,topic:"4.5.2",qtype:"concept",difficulty:2,stem:"In a fractional factorial, what is the difference between **aliasing** and **confounding**?",options:["Aliasing happens only in full factorials; confounding only in fractions","Aliasing makes effects larger; confounding makes them smaller","Confounding can always be removed in the analysis; aliasing cannot","They describe the same idea — effects that cannot be separated; “confounding” is also used for blocks or outside variables mixed with effects"],answer:3,hint:"Alias = confounded effects within the design; confounding also with blocks or lurking variables.",steps:[{title:"Key idea",body:"Both words mean that two sources of variation share a column, so their separate effects cannot be estimated."},{title:"Usage",body:"Texts use “alias” for fractional factorial structures and “confound” for blocks and lurking variables, but the meaning is the same."}],final:"Same idea, different context → answer **D**",whyWrong:["Aliasing is a fractional-factorial concept; full factorials have no aliasing unless blocked.","Neither term describes the direction of change.","Neither can be removed without new runs or assumptions.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb308",phase:4,topic:"4.5.2",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “Multiplying an effect by each word of the defining relation gives that effect’s [?] — the effects that share its column.”",options:["residuals","aliases","generators","blocks"],answer:1,hint:"Alias(X) = X × word, with squared letters cancelling.",steps:[{title:"Key idea",body:"The alias chain of an effect lists every effect with the same contrast column."},{title:"Example",body:"With I = ABCD: A = BCD, AB = CD."}],final:"Aliases → answer **B**",whyWrong:["Residuals are observed minus fitted values.","","Generators define the design; aliases are derived from them.","Blocks are groups of runs."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb309",phase:4,topic:"4.5.2",qtype:"scenario",difficulty:3,stem:"A $2^{5-2}_{III}$ screening experiment on **fibre-install time** with D = AB and E = AC shows large effects in the A, B and D columns. Process experts say D (cable type) should matter little. What is a plausible explanation?",options:["D must be active because its column is significant","A and B are aliased with each other","The D column also estimates AB; with A and B both active, the AB interaction may be what appears as “D”","The experiment failed because D cannot be estimated"],answer:2,hint:"Heredity: if A and B are active, AB is a plausible cause of a significant D = AB column.",steps:[{title:"Alias",body:"$$D\\times ABD=AB\\Rightarrow\\ \\ell_D=D+AB+\\dots$$"},{title:"Reasoning",body:"A and B are both strong, so their interaction is plausible (heredity), while D is doubtful on technical grounds."},{title:"Confirm",body:"A fold-over on D (reverse D’s signs only) separates D from AB."}],final:"It may be AB, not D → answer **C**",whyWrong:["The D column is D + AB + …; the AB interaction may explain it.","A and B have different columns; they are aliased with other interactions, not with each other.","","D is estimable but aliased with AB."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb310",phase:4,topic:"4.5.2",qtype:"best-action",difficulty:3,stem:"A Resolution III design shows a significant column that is aliased as **C + AB**. The team wants **C and every two-factor interaction involving C** to be clear of the other main effects and two-factor interactions, using one extra block of runs. What is the BEST follow-up?",options:["A single-factor fold-over: rerun the design with only C’s signs reversed","A full fold-over reversing every factor","Replicate the original runs","Add center points"],answer:0,hint:"Single-factor fold-over: C and all two-factor interactions involving C become clear.",steps:[{title:"Key idea",body:"Reversing only C changes the sign of C (and of every interaction containing C) but not AB. Combining both fractions separates C from AB and makes every two-factor interaction with C clear."},{title:"Use",body:"This targets the effect of interest with one extra block of runs."}],final:"Fold over on C → answer **A**",whyWrong:["","A full fold-over clears every main effect of two-factor interactions, but the two-factor interactions involving C stay aliased with other two-factor interactions.","Replication keeps the same aliasing.","Center points do not change the factorial columns."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb311",phase:4,topic:"4.5.2",qtype:"concept",difficulty:2,stem:"How does an **aliased** effect estimate behave if two effects in the same chain have opposite signs (e.g. A = +5 and BCD = −5)?",options:["They double, so the column looks twice as large","The software reports both effects separately","The column becomes the constant term","They cancel, so the column can look inactive even though both effects are real"],answer:3,hint:"Aliased estimate = algebraic sum → cancellation is possible.",steps:[{title:"Key idea",body:"The estimate is A + BCD = +5 + (−5) = 0. A real effect can be hidden."},{title:"Lesson",body:"Fractional designs rely on the assumption that one member of each chain dominates."}],final:"They can cancel → answer **D**",whyWrong:["That would happen only if both had the same sign.","Aliased effects cannot be reported separately.","Only words of the defining relation are aliased with I.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb312",phase:4,topic:"4.5.2",qtype:"statements",difficulty:2,stem:`With I = ABCDE in a $2^{5-1}$ design, which statements are correct?

1. Each main effect is aliased with a four-factor interaction.
2. Each two-factor interaction is aliased with a three-factor interaction.
3. AB and CD are aliased.
4. The design has 16 runs.`,options:["1, 2 and 4 only","1 and 3 only","1, 2, 3 and 4","2 and 4 only"],answer:0,hint:"Alias = effect × ABCDE.",steps:[{title:"Check each",body:"1 True: A = BCDE. 2 True: AB = CDE. 3 False. 4 True: $2^{5-1}$ = 16."},{title:"Decide",body:"Statements 1, 2 and 4 — this is the Resolution V half fraction."}],final:"1, 2, 4 → answer **A**",whyWrong:["","Statement 3 is false; statements 2 and 4 are true.","Statement 3 is false: AB × ABCDE = CDE, so AB is aliased with CDE, not CD.","Statement 1 is also true: A × ABCDE = BCDE."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb313",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:3,stem:"A $2^{6-2}$ design on **MPLS failover time** has the defining relation **I = ABCE = ADEF = BCDF**. What is the complete alias set of **AD**?",options:["AD = ADEF = ABCDE = ABCDF","AD = BCDE","AD = ABCF = BCDE","AD = EF = ABCF = BCDE"],answer:3,hint:"Alias of an effect = effect × each word of the defining relation, with squared letters cancelling.",steps:[{title:"Defining relation",body:"I = ABCE = ADEF = BCDF."},{title:"Multiply",body:"$$AD\\times ABCE=BCDE\\quad AD\\times ADEF=EF\\quad AD\\times BCDF=ABCF$$"},{title:"Rule",body:"Any letter that appears twice cancels, because each ±1 column squared is a column of 1’s (I)."},{title:"Alias chain",body:"AD = EF = ABCF = BCDE: the estimate labelled AD is really AD + EF + ABCF + BCDE."}],final:"AD = EF = ABCF = BCDE → answer **D**",whyWrong:["Letters were combined without cancelling: a letter that appears twice (e.g. A × A) becomes I and drops out.","Only the first generator word was used; every word of the defining relation, including products of generators, gives an alias.","The generalized interaction (the product of the generator words) was forgotten, so one alias is missing.",""],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb314",phase:4,topic:"4.5.2",qtype:"calculation",difficulty:2,stem:"A $2^4$ design on **router boot time** is split into **2 blocks** with **ABCD** confounded with blocks. How many runs are in each block, and which block contains run **acd**?",options:["8 runs per block; acd is in the ABCD = +1 block","8 runs per block; acd is in the ABCD = −1 block","4 runs per block; acd is in the ABCD = −1 block","16 runs per block; acd is in both blocks"],answer:1,hint:"Block sign of a run = product of its factor signs for the confounded interaction; runs per block = N ÷ blocks.",steps:[{title:"Runs per block",body:"$$\\dfrac{2^4}{2}=\\dfrac{16}{2}=8$$"},{title:"Sign of ABCD for acd",body:"$$(+1)\\times(-1)\\times(+1)\\times(+1)=-1$$"},{title:"Rule of thumb",body:"Runs with an even number of letters ((1), ab, ac, …, abcd) have ABCD = +1; runs with an odd number (a, b, …, acd) have ABCD = −1."}],final:"8 per block; acd in −1 block → answer **B**",whyWrong:["For acd: A = +, B = −, C = +, D = + → product = −1. One minus sign makes the product negative.","","A $2^4$ has 16 runs; two blocks hold 8 each.","Each run appears once; the 16 runs are split 8 and 8."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb315",phase:4,topic:"4.5.2",qtype:"concept",difficulty:3,stem:"In a replicated $2^3$ run in blocks, the team confounds **ABC** with blocks in replicate 1 but **AB** with blocks in replicate 2. What is this called and what is its benefit?",options:["Complete confounding — ABC and AB are lost entirely","A fold-over — it doubles the resolution","Partial confounding — every interaction can still be estimated from the replicates in which it is not confounded","Aliasing — AB and ABC become aliased with each other"],answer:2,hint:"Partial confounding spreads the loss of information across different effects.",steps:[{title:"Key idea",body:"Confounding a different effect in each replicate means no effect is lost completely. ABC is estimated from replicate 2 and AB from replicate 1."},{title:"Cost",body:"Those effects are estimated with less precision than unconfounded ones."}],final:"Partial confounding → answer **C**",whyWrong:["Each is confounded in only one replicate, so information remains from the other.","Fold-over refers to reversing signs of a fraction, not to blocking replicates.","","They are each confounded with blocks in different replicates; they are not aliased with each other."],bookRef:"Syllabus 4.5.2"},{id:"sv-4-bb316",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:1,stem:"A $2^{4-1}$ design for **VPN set-up time** uses **D = ABC**. What is its resolution?",options:["Resolution III","Resolution V","Resolution IV","Resolution VI"],answer:2,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$D=ABC\\Rightarrow I=D\\times D=ABC\\times D=ABCD$$ Generators → I = ABCD."},{title:"Defining relation",body:"I = ABCD."},{title:"Shortest word",body:"Word lengths: ABCD = 4 → shortest = 4. $$R=4\\ \\Rightarrow\\ 2^{4-1}_{IV}$$"},{title:"Meaning",body:"Main effects are clear of two-factor interactions, but two-factor interactions are aliased with each other."}],final:"Resolution IV → answer **C**",whyWrong:["The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).","","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators)."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb317",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:1,stem:"A $2^{3-1}$ design for **IPTV zapping delay** uses **C = AB**. What is its resolution?",options:["Resolution III","Resolution II","Resolution IV","Resolution V"],answer:0,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$C=AB\\Rightarrow I=C\\times C=AB\\times C=ABC$$ Generators → I = ABC."},{title:"Defining relation",body:"I = ABC."},{title:"Shortest word",body:"Word lengths: ABC = 3 → shortest = 3. $$R=3\\ \\Rightarrow\\ 2^{3-1}_{III}$$"},{title:"Meaning",body:"Main effects are aliased with two-factor interactions."}],final:"Resolution III → answer **A**",whyWrong:["","The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators)."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb318",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:1,stem:"A $2^{5-1}$ design for **API latency** uses **E = ABCD**. What is its resolution?",options:["Resolution IV","Resolution V","Resolution VI","Resolution VII"],answer:1,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$E=ABCD\\Rightarrow I=E\\times E=ABCD\\times E=ABCDE$$ Generators → I = ABCDE."},{title:"Defining relation",body:"I = ABCDE."},{title:"Shortest word",body:"Word lengths: ABCDE = 5 → shortest = 5. $$R=5\\ \\Rightarrow\\ 2^{5-1}_{V}$$"},{title:"Meaning",body:"Main effects and two-factor interactions are clear of each other (2FIs aliased with 3FIs)."}],final:"Resolution V → answer **B**",whyWrong:["The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators)."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb319",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:2,stem:"A $2^{5-2}$ design for **order fallout** uses **D = AB and E = AC**. What is its resolution?",options:["Resolution II","Resolution IV","Resolution V","Resolution III"],answer:3,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$D=AB\\Rightarrow I=D\\times D=AB\\times D=ABD$$ Generators → I = ABD, I = ACE; product(s) → BCDE."},{title:"Defining relation",body:"I = ABD = ACE = BCDE."},{title:"Shortest word",body:"Word lengths: ABD = 3, ACE = 3, BCDE = 4 → shortest = 3. $$R=3\\ \\Rightarrow\\ 2^{5-2}_{III}$$"},{title:"Meaning",body:"Main effects are aliased with two-factor interactions."}],final:"Resolution III → answer **D**",whyWrong:["The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","The longest word was used; resolution is the length of the SHORTEST word.","Resolution is not the number of factors; it is the length of the shortest word.",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb320",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:2,stem:"A $2^{6-2}$ design for **data-centre PUE** uses **E = ABC and F = BCD**. What is its resolution?",options:["Resolution III","Resolution V","Resolution IV","Resolution VI"],answer:2,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$E=ABC\\Rightarrow I=E\\times E=ABC\\times E=ABCE$$ Generators → I = ABCE, I = BCDF; product(s) → ADEF."},{title:"Defining relation",body:"I = ABCE = ADEF = BCDF."},{title:"Shortest word",body:"Word lengths: ABCE = 4, ADEF = 4, BCDF = 4 → shortest = 4. $$R=4\\ \\Rightarrow\\ 2^{6-2}_{IV}$$"},{title:"Meaning",body:"Main effects are clear of two-factor interactions, but two-factor interactions are aliased with each other."}],final:"Resolution IV → answer **C**",whyWrong:["The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).","","Resolution is not the number of factors; it is the length of the shortest word."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb321",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:3,stem:"A $2^{7-4}$ design for **call-centre service level** uses **D = AB, E = AC, F = BC and G = ABC**. What is its resolution?",options:["Resolution III","Resolution II","Resolution VII","Resolution IV"],answer:0,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$D=AB\\Rightarrow I=D\\times D=AB\\times D=ABD$$ Generators → I = ABD, I = ACE, I = BCF, I = ABCG; product(s) → AFG, BEG, CDG, DEF, ABEF, ACDF, ADEG, BCDE, BDFG, CEFG, ABCDEFG."},{title:"Defining relation",body:"I = ABD = ACE = AFG = BCF = BEG = CDG = DEF = ABCG = ABEF = ACDF = ADEG = BCDE = BDFG = CEFG = ABCDEFG."},{title:"Shortest word",body:"Word lengths: ABD = 3, ACE = 3, AFG = 3, BCF = 3, BEG = 3, CDG = 3, DEF = 3, ABCG = 4, ABEF = 4, ACDF = 4, ADEG = 4, BCDE = 4, BDFG = 4, CEFG = 4, ABCDEFG = 7 → shortest = 3. $$R=3\\ \\Rightarrow\\ 2^{7-4}_{III}$$"},{title:"Meaning",body:"Main effects are aliased with two-factor interactions."}],final:"Resolution III → answer **A**",whyWrong:["","The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","The longest word was used; resolution is the length of the SHORTEST word.","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators)."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb322",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:2,stem:"A $2^{6-1}$ design for **fibre-splice loss** uses **F = ABCDE**. What is its resolution?",options:["Resolution V","Resolution VII","Resolution VIII","Resolution VI"],answer:3,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$F=ABCDE\\Rightarrow I=F\\times F=ABCDE\\times F=ABCDEF$$ Generators → I = ABCDEF."},{title:"Defining relation",body:"I = ABCDEF."},{title:"Shortest word",body:"Word lengths: ABCDEF = 6 → shortest = 6. $$R=6\\ \\Rightarrow\\ 2^{6-1}_{VI}$$"},{title:"Meaning",body:"Main effects are aliased with five-factor and 2FIs with four-factor interactions."}],final:"Resolution VI → answer **D**",whyWrong:["The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb323",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:3,stem:"A $2^{5-2}$ design for **SMS throughput** uses **D = ABC and E = AB**. What is its resolution?",options:["Resolution II","Resolution III","Resolution IV","Resolution V"],answer:1,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$D=ABC\\Rightarrow I=D\\times D=ABC\\times D=ABCD$$ Generators → I = ABCD, I = ABE; product(s) → CDE."},{title:"Defining relation",body:"I = ABE = CDE = ABCD."},{title:"Shortest word",body:"Word lengths: ABE = 3, CDE = 3, ABCD = 4 → shortest = 3. $$R=3\\ \\Rightarrow\\ 2^{5-2}_{III}$$"},{title:"Meaning",body:"Main effects are aliased with two-factor interactions."}],final:"Resolution III → answer **B**",whyWrong:["The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","","The longest word was used; resolution is the length of the SHORTEST word.","Resolution is not the number of factors; it is the length of the shortest word."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb324",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:3,stem:"A $2^{6-2}$ design for **ticket backlog** uses **E = ABC and F = ABD**. What is its resolution?",options:["Resolution III","Resolution IV","Resolution V","Resolution VI"],answer:1,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$E=ABC\\Rightarrow I=E\\times E=ABC\\times E=ABCE$$ Generators → I = ABCE, I = ABDF; product(s) → CDEF."},{title:"Defining relation",body:"I = ABCE = ABDF = CDEF."},{title:"Shortest word",body:"Word lengths: ABCE = 4, ABDF = 4, CDEF = 4 → shortest = 4. $$R=4\\ \\Rightarrow\\ 2^{6-2}_{IV}$$"},{title:"Meaning",body:"Main effects are clear of two-factor interactions, but two-factor interactions are aliased with each other."}],final:"Resolution IV → answer **B**",whyWrong:["The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).","Resolution is not the number of factors; it is the length of the shortest word."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb325",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:1,stem:"What is the **highest** resolution a $2^{5-1}$ half fraction can have, and which generator gives it?",options:["Resolution IV, with the new factor = product of all 4 base factors","Resolution V, with the new factor = AB","Resolution V, with the new factor = product of all 4 base factors","Resolution VI, with the new factor = product of all 4 base factors"],answer:2,hint:"Half fraction: single word; best word uses all k letters → Resolution k.",steps:[{title:"Idea",body:"A half fraction has one word, so its resolution equals the length of that word."},{title:"Best generator",body:"Use the highest-order interaction of the base factors: E = ABCD → I = ABCDE."},{title:"Result",body:"$$R=k=5\\ \\Rightarrow\\ 2^{5-1}_{V}$$ with $2^{4}$ = 16 runs, i.e. $2^5\\times\\dfrac{1}{2}$."}],final:"Resolution V → answer **C**",whyWrong:["The word includes the generated letter: it has 5 letters, so the resolution is V.","A generator such as AB gives a 3-letter word and only Resolution III.","","A word cannot be longer than the number of factors (5)."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb326",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:1,stem:"What is the **highest** resolution a $2^{4-1}$ half fraction can have, and which generator gives it?",options:["Resolution III, with the new factor = product of all 3 base factors","Resolution IV, with the new factor = AB","Resolution V, with the new factor = product of all 3 base factors","Resolution IV, with the new factor = product of all 3 base factors"],answer:3,hint:"Half fraction: single word; best word uses all k letters → Resolution k.",steps:[{title:"Idea",body:"A half fraction has one word, so its resolution equals the length of that word."},{title:"Best generator",body:"Use the highest-order interaction of the base factors: D = ABC → I = ABCD."},{title:"Result",body:"$$R=k=4\\ \\Rightarrow\\ 2^{4-1}_{IV}$$ with $2^{3}$ = 8 runs, i.e. $2^4\\times\\dfrac{1}{2}$."}],final:"Resolution IV → answer **D**",whyWrong:["The word includes the generated letter: it has 4 letters, so the resolution is IV.","A generator such as AB gives a 3-letter word and only Resolution III.","A word cannot be longer than the number of factors (4).",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb327",phase:4,topic:"4.5.3",qtype:"scenario",difficulty:2,stem:"A team needs main effects and **two-factor interactions clear of each other** (at least Resolution V) for **6 factors** on **5G slice latency**. What is the smallest regular two-level fractional factorial that achieves this?",options:["32 runs ($2^{6-1}_{VI}$)","16 runs ($2^{6-2}_{IV}$)","8 runs ($2^{6-3}_{III}$)","64 runs ($2^6$ full factorial)"],answer:0,hint:"Standard design table: 6 factors → 8 runs III, 16 runs IV, 32 runs VI.",steps:[{title:"Requirement",body:"Resolution ≥ V."},{title:"Check 16 runs",body:"$$2^{6-2}:\\ \\text{two generators};\\ \\text{the best choice gives}\\ I=ABCE=BCDF=ADEF\\Rightarrow IV$$"},{title:"Check 32 runs",body:"$$2^{6-1}:\\ F=ABCDE\\Rightarrow I=ABCDEF\\Rightarrow VI$$ which satisfies ≥ V."},{title:"Decide",body:"32 runs is the smallest."}],final:"32 runs, Res VI → answer **A**",whyWrong:["","With 16 runs the best 6-factor design is Resolution IV: two-factor interactions are aliased with each other.","Resolution III aliases main effects with two-factor interactions.","This works but is not the smallest; the half fraction already reaches Resolution VI."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb328",phase:4,topic:"4.5.3",qtype:"concept",difficulty:3,stem:"For **5 factors**, the standard two-level fractions are $2^{5-2}$ (8 runs) and $2^{5-1}$ (16 runs). What are their best achievable resolutions?",options:["8 runs: Resolution IV; 16 runs: Resolution V","8 runs: Resolution III; 16 runs: Resolution IV","8 runs: Resolution II; 16 runs: Resolution V","8 runs: Resolution III; 16 runs: Resolution V"],answer:3,hint:"Half fraction best = k letters; quarter fraction of 5 factors best = III.",steps:[{title:"16 runs",body:"$$E=ABCD\\Rightarrow I=ABCDE\\Rightarrow R=5\\ (V)$$"},{title:"8 runs",body:"$$D=AB,\\ E=AC\\Rightarrow I=ABD=ACE=BCDE\\Rightarrow R=3\\ (III)$$"},{title:"Why not IV in 8 runs",body:"Two 4-letter words from base factors A, B, C would both need to be ABC + new letter (ABCD and ABCE), and their product DE has only 2 letters (Resolution II). So III is the best."}],final:"III and V → answer **D**",whyWrong:["With two generators in 8 runs, the product of the two words always leaves a word of 3 or fewer letters for some choice; the best possible is III.","E = ABCD gives I = ABCDE, Resolution V.","Generators D = AB, E = AC give shortest word 3, so Resolution III is achievable.",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb329",phase:4,topic:"4.5.3",qtype:"concept",difficulty:2,stem:"In a **Resolution IV** design, what is the lowest-order interaction that a **main effect** can be aliased with, and what is the lowest-order interaction a **two-factor interaction** can be aliased with?",options:["Main effect → three-factor interaction; 2FI → two-factor interaction","Main effect → two-factor interaction; 2FI → main effect","Main effect → four-factor interaction; 2FI → three-factor interaction","Main effect → three-factor interaction; 2FI → three-factor interaction"],answer:0,hint:"In Resolution R, an effect of order a can be aliased with one of order b only if a + b ≥ R.",steps:[{title:"Rule",body:"$$a+b\\ge R$$"},{title:"Main effects (a = 1)",body:"$$1+b\\ge 4\\Rightarrow b\\ge 3$$"},{title:"2FIs (a = 2)",body:"$$2+b\\ge 4\\Rightarrow b\\ge 2$$ so 2FIs can be aliased with other 2FIs."}],final:"1 ↔ 3, 2 ↔ 2 → answer **A**",whyWrong:["","That is Resolution III.","That is Resolution V.","In Resolution IV, 2 + 2 = 4, so two-factor interactions can be aliased with each other."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb330",phase:4,topic:"4.5.3",qtype:"concept",difficulty:1,stem:"How is the **resolution** of a regular fractional factorial defined?",options:["The number of factors in the design","The number of letters in the shortest word of the defining relation","The number of generators p","The number of runs divided by the number of factors"],answer:1,hint:"Resolution = shortest word length (Roman numeral subscript).",steps:[{title:"Key idea",body:"Shorter words mean low-order effects are aliased with each other. The shortest word sets the worst case."},{title:"Notation",body:"$2^{5-1}_V$ means Resolution V."}],final:"Shortest word length → answer **B**",whyWrong:["The number of factors is k; resolution depends on the generators.","","p sets the fraction size, not the resolution.","Resolution is not a ratio of runs to factors."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb331",phase:4,topic:"4.5.3",qtype:"concept",difficulty:1,stem:"In a **Resolution III** design, which statement is true?",options:["Main effects are aliased with other main effects","Main effects are clear of all two-factor interactions","Main effects are not aliased with other main effects, but they are aliased with two-factor interactions","Two-factor interactions are clear of each other"],answer:2,hint:"III: 1 + 2 = 3 → mains aliased with 2FIs.",steps:[{title:"Key idea",body:"Resolution III designs are the most economical screening designs, but each main-effect estimate may contain two-factor interactions."},{title:"Use",body:"Screening when interactions are assumed small."}],final:"Mains aliased with 2FIs → answer **C**",whyWrong:["That would be Resolution II, which is not useful.","That needs Resolution IV or higher.","","That needs Resolution V."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb332",phase:4,topic:"4.5.3",qtype:"concept",difficulty:1,stem:"In a **Resolution V** design, which statement is true?",options:["Main effects are aliased with two-factor interactions","Two-factor interactions are aliased with other two-factor interactions","No effects are aliased at all","Main effects and two-factor interactions are not aliased with each other or with other two-factor interactions"],answer:3,hint:"V: 2 + 3 = 5 → 2FIs aliased only with 3FIs or higher.",steps:[{title:"Key idea",body:"Resolution V lets you estimate every main effect and every two-factor interaction, assuming three-factor and higher interactions are negligible."},{title:"Use",body:"Characterization when budget prevents a full factorial."}],final:"Mains and 2FIs all clear → answer **D**",whyWrong:["That is Resolution III.","That is Resolution IV.","Only a full factorial has no aliasing; in Resolution V, 2FIs are aliased with 3FIs.",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb333",phase:4,topic:"4.5.3",qtype:"scenario",difficulty:2,stem:"A Black Belt must choose a design to **screen 10 factors** for **mobile-app crash rate** with a small budget, assuming interactions are negligible at this stage. Which resolution is usually appropriate?",options:["Resolution III","Resolution V","Resolution II","A full factorial (no aliasing)"],answer:0,hint:"Screening → III (or IV if affordable); characterization → V or full.",steps:[{title:"Key idea",body:"At the screening stage the goal is to find the vital few main effects cheaply. Resolution III (e.g. 16 runs) does this if interactions are small."},{title:"Safety net",body:"If results are ambiguous, a fold-over raises it to Resolution IV."}],final:"Resolution III → answer **A**",whyWrong:["","Resolution V for 10 factors needs many more runs than a screening budget usually allows.","Resolution II aliases main effects with each other, which is useless.","$2^{10}$ = 1,024 runs is far too many for screening."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb334",phase:4,topic:"4.5.3",qtype:"scenario",difficulty:2,stem:"After screening, **5 vital factors** for **network latency** remain and the team needs to estimate **all two-factor interactions**. They can afford 16 runs. Which design should they choose?",options:["$2^{5-2}_{III}$","$2^{5-1}_V$","A 12-run Plackett–Burman","$2^{5-1}_{IV}$ with E = ABC"],answer:1,hint:"Need clear 2FIs → Resolution V.",steps:[{title:"Key idea",body:"Resolution V separates all main effects and two-factor interactions from each other."},{title:"Design",body:"E = ABCD → I = ABCDE, 16 runs."}],final:"$2^{5-1}_V$ → answer **B**",whyWrong:["Resolution III aliases main effects with two-factor interactions.","","Plackett–Burman designs do not give clear two-factor interactions.","E = ABC gives a 4-letter word (Resolution IV), which aliases some 2FIs in pairs; E = ABCD gives V."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb335",phase:4,topic:"4.5.3",qtype:"statements",difficulty:2,stem:`Which statements about resolution are correct?

1. Higher resolution generally requires more runs for the same number of factors.
2. A full factorial has no aliasing, so it is often described as having “full” resolution.
3. A Resolution IV design aliases main effects with two-factor interactions.
4. A full fold-over of a Resolution III design gives Resolution IV.`,options:["1 and 3 only","2, 3 and 4 only","1, 2 and 4 only","1, 2, 3 and 4"],answer:2,hint:"Resolution ↑ ⇒ runs ↑; full factorial = no aliasing; IV: mains clear of 2FIs.",steps:[{title:"Check each",body:"1 True. 2 True. 3 False. 4 True — fold-over cancels the odd-length (3-letter) words."},{title:"Decide",body:"Statements 1, 2 and 4."}],final:"1, 2, 4 → answer **C**",whyWrong:["Statement 3 is false (that is Resolution III), and statements 2 and 4 are true.","Statement 3 is false and statement 1 is true.","","Statement 3 is false: in Resolution IV main effects are aliased with three-factor interactions."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb336",phase:4,topic:"4.5.3",qtype:"not-except",difficulty:2,stem:"All of the following are correct about **Resolution IV** designs EXCEPT:",options:["Main effects are clear of two-factor interactions","Main effects may be aliased with three-factor interactions","They are a good choice when main effects must be estimated cleanly but some 2FIs can be left aliased","All two-factor interactions can be estimated free of each other"],answer:3,hint:"IV: 2FIs are aliased with other 2FIs.",steps:[{title:"Key idea",body:"2 + 2 = 4, so in Resolution IV some two-factor interactions share columns (e.g. AB + CD)."},{title:"Odd one out",body:"Clear 2FIs require Resolution V."}],final:"2FIs not all clear → answer **D**",whyWrong:["True for Resolution IV.","True: 1 + 3 = 4.","True: a common use of Resolution IV.",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb337",phase:4,topic:"4.5.3",qtype:"true-false",difficulty:1,stem:"True or false: a $2^{3-1}_{III}$ design aliases each main effect with a two-factor interaction.",options:["True","False"],answer:0,hint:"Resolution III: 1 + 2 = 3.",steps:[{title:"Compute",body:"$$A\\times ABC=BC\\quad B\\times ABC=AC\\quad C\\times ABC=AB$$"},{title:"Conclusion",body:"Each main effect shares its column with a two-factor interaction."}],final:"True → answer **True**",whyWrong:["","With I = ABC, A = BC, B = AC and C = AB."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb338",phase:4,topic:"4.5.3",qtype:"true-false",difficulty:2,stem:"True or false: if two fractional factorial designs have the same number of runs and factors, they always have the same resolution.",options:["True","False"],answer:1,hint:"Generators decide resolution.",steps:[{title:"Key idea",body:"Different generators give different defining relations and therefore different shortest words."},{title:"Practice",body:"Software picks generators that maximize resolution (and minimize aberration) by default."}],final:"False → answer **False**",whyWrong:["Resolution depends on the generators chosen, not only on the run count. For example, a $2^{5-1}$ with E = AB is Resolution III, while E = ABCD gives Resolution V.",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb339",phase:4,topic:"4.5.3",qtype:"missing-word",difficulty:1,stem:"Complete the sentence: “The design notation $2^{7-4}_{III}$ tells you that the design has 7 factors, 8 runs, 4 generators and resolution [?].”",options:["IV","VII","III","IV, because p = 4"],answer:2,hint:"$2^{k-p}_R$: k factors, p generators, $2^{k-p}$ runs, resolution R.",steps:[{title:"Read",body:"k = 7, p = 4, runs $2^{3}$ = 8, R = III."},{title:"Meaning",body:"Saturated screening design: main effects aliased with two-factor interactions."}],final:"III → answer **C**",whyWrong:["The subscript is III.","The 7 is the number of factors, not the resolution.","","p is the number of generators; resolution is the subscript."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb340",phase:4,topic:"4.5.3",qtype:"best-action",difficulty:2,stem:"A Resolution III screen of 7 factors on **broadband installation time** found 3 apparently strong main effects, but engineers suspect some are really two-factor interactions. What is the BEST next step?",options:["Accept the 3 main effects and move to optimization","Run a full fold-over to obtain a Resolution IV combined design, then re-analyze","Repeat the same 8 runs","Start again with a full $2^7$"],answer:1,hint:"Res III ambiguity → full fold-over → Res IV.",steps:[{title:"Key idea",body:"Combining the original runs with the mirror-image runs cancels the 3-letter words, so main effects become clear of two-factor interactions."},{title:"Cost",body:"Only one extra block of 8 runs."}],final:"Full fold-over → answer **B**",whyWrong:["Ambiguity in Resolution III should be resolved first.","","Replication does not change aliasing.","128 runs is unnecessary; a fold-over uses only 8 more."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb341",phase:4,topic:"4.5.3",qtype:"concept",difficulty:2,stem:"Why is a **Resolution II** design not used in practice?",options:["Main effects would be aliased with other main effects, so even the basic factor effects could not be separated","It needs more runs than a full factorial","It cannot be randomized","It cannot include center points"],answer:0,hint:"Resolution II: 1 + 1 = 2 → main effect = main effect.",steps:[{title:"Key idea",body:"A 2-letter word such as I = AB means A and B have the same column; their effects cannot be told apart."},{title:"Rule",body:"Useful fractional designs have Resolution III or higher."}],final:"Mains aliased with mains → answer **A**",whyWrong:["","It would need fewer runs; the problem is aliasing.","Any design can be randomized.","Center points could be added; that is not the problem."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb342",phase:4,topic:"4.5.3",qtype:"concept",difficulty:2,stem:"Two $2^{7-2}$ designs are both Resolution IV. What does **minimum aberration** mean when choosing between them?",options:["Prefer the design with the most center points","Prefer the design with the fewest shortest (length-4) words, so fewer two-factor interactions are aliased with each other","Prefer the design with the largest number of runs","Prefer the design whose generators use the fewest letters"],answer:1,hint:"Same resolution → choose minimum aberration (fewest words of minimum length).",steps:[{title:"Key idea",body:"Resolution only looks at the shortest word length. Among designs with equal resolution, the one with fewer such words has fewer aliased low-order effects."},{title:"Practice",body:"Minitab’s default generators give minimum-aberration designs."}],final:"Fewest shortest words → answer **B**",whyWrong:["Center points do not affect aberration.","","Both have the same number of runs.","Short generators usually produce short words, which is the opposite of the aim."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb343",phase:4,topic:"4.5.3",qtype:"scenario",difficulty:3,stem:"A team plans a $2^{6-2}$ design on **cloud cost** with generators E = AB and F = CD (instead of Minitab’s defaults). What is the problem?",options:["There is no problem; all 16-run designs for 6 factors are the same","The design will be Resolution V because ABCDEF has 6 letters","The design is not balanced","The words ABE, CDF and ABCDEF give Resolution III, whereas E = ABC and F = BCD would give Resolution IV for the same 16 runs"],answer:3,hint:"Choose generators that maximize the shortest word length.",steps:[{title:"Defining relation",body:"$$I=ABE=CDF=ABCDEF$$ Shortest word = 3 → Resolution III."},{title:"Better choice",body:"$$E=ABC,\\ F=BCD\\Rightarrow I=ABCE=BCDF=ADEF\\Rightarrow IV$$"},{title:"Decide",body:"Use the higher-resolution generators: same cost, cleaner main effects."}],final:"Poor generators → Res III → answer **D**",whyWrong:["Generators change the defining relation and therefore the resolution.","Resolution uses the shortest word (3 letters here), not the longest.","Every regular fraction is balanced; the issue is aliasing.",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb344",phase:4,topic:"4.5.3",qtype:"concept",difficulty:2,stem:"How does increasing resolution affect the experiment **budget** for a fixed number of factors?",options:["Higher resolution generally needs more runs, because fewer generators (a smaller fraction) are allowed","Higher resolution always needs fewer runs","Resolution and run count are unrelated","Higher resolution needs more factors"],answer:0,hint:"Trade-off: runs ↔ resolution.",steps:[{title:"Example",body:"Six factors: 8 runs → III, 16 runs → IV, 32 runs → VI."},{title:"Decision",body:"Choose the lowest resolution that still protects the effects you need to estimate."}],final:"More runs → answer **A**",whyWrong:["","The opposite is true: less aliasing requires more runs.","For a fixed k, longer words need fewer generators, so a larger fraction.","The number of factors is fixed by the problem."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb345",phase:4,topic:"4.5.3",qtype:"sequence",difficulty:2,stem:"Order these design choices for **6 factors** from **lowest to highest resolution** (best achievable): P. 16-run fraction  Q. 8-run fraction  R. 32-run fraction",options:["P (IV) → Q (III) → R (VI)","Q (III) → R (VI) → P (IV)","Q (III) → P (IV) → R (VI)","R (VI) → P (IV) → Q (III)"],answer:2,hint:"More runs (smaller p) → longer possible words → higher resolution.",steps:[{title:"8 runs",body:"$2^{6-3}_{III}$."},{title:"16 runs",body:"$2^{6-2}_{IV}$."},{title:"32 runs",body:"$2^{6-1}_{VI}$ with F = ABCDE."}],final:"Q → P → R → answer **C**",whyWrong:["The 8-run fraction has the lowest resolution (III).","The 32-run half fraction has the highest resolution.","","This is highest to lowest, the reverse order."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb346",phase:4,topic:"4.5.3",qtype:"concept",difficulty:2,stem:"A Resolution IV design projects into a **full factorial** in how many factors (any choice of them)?",options:["Any 4 factors","Any 2 factors only","All factors","Any 3 factors"],answer:3,hint:"Resolution R → full factorial in any R − 1 factors.",steps:[{title:"Key idea",body:"Because no word has fewer than 4 letters, any 3 factors appear in no word together, so their columns form a complete $2^3$ (possibly replicated)."},{title:"Use",body:"If only 3 factors are active, the data become a full factorial in them."}],final:"Any 3 factors → answer **D**",whyWrong:["A design of resolution R projects into a full factorial in any R − 1 factors, so 3 for Resolution IV.","Two factors is the projection of Resolution III.","Only the full factorial projects onto all factors.",""],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb347",phase:4,topic:"4.5.3",qtype:"best-action",difficulty:2,stem:"A Minitab screening design for **8 factors** offers 16 runs (Resolution IV) or 32 runs (Resolution IV). The budget allows 32 runs. What extra benefit can the 32-run option give if resolution is the same?",options:["Main effects become clear of two-factor interactions only in the 32-run design","Fewer aliased two-factor-interaction pairs (lower aberration) and more degrees of freedom to estimate effects and error","The 32-run design is a full factorial","There is no benefit at all; the designs are identical"],answer:1,hint:"Same resolution ≠ same alias structure; compare the alias tables.",steps:[{title:"Key idea",body:"The 32-run design has more columns (31 vs 15), so fewer two-factor interactions need to share a column."},{title:"Decide",body:"Look at the alias structure to see which interactions of interest become clear."}],final:"Less aliasing among 2FIs → answer **B**",whyWrong:["Both designs are Resolution IV, so main effects are already clear in both.","","A full $2^8$ needs 256 runs.","Same resolution does not mean the same alias structure."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb348",phase:4,topic:"4.5.3",qtype:"calculation",difficulty:3,stem:"A $2^{7-3}$ design for **core-router convergence time** uses **E = ABC, F = BCD and G = ACD**. What is its resolution?",options:["Resolution IV","Resolution III","Resolution V","Resolution VII"],answer:0,hint:"Resolution = length (number of letters) of the shortest word in the complete defining relation.",steps:[{title:"Words",body:"$$E=ABC\\Rightarrow I=E\\times E=ABC\\times E=ABCE$$ Generators → I = ABCE, I = BCDF, I = ACDG; product(s) → ABFG, ADEF, BDEG, CEFG."},{title:"Defining relation",body:"I = ABCE = ABFG = ACDG = ADEF = BCDF = BDEG = CEFG."},{title:"Shortest word",body:"Word lengths: ABCE = 4, ABFG = 4, ACDG = 4, ADEF = 4, BCDF = 4, BDEG = 4, CEFG = 4 → shortest = 4. $$R=4\\ \\Rightarrow\\ 2^{7-3}_{IV}$$"},{title:"Meaning",body:"Main effects are clear of two-factor interactions, but two-factor interactions are aliased with each other."}],final:"Resolution IV → answer **A**",whyWrong:["","The number of letters on the right-hand side of the generator was used; the word includes the generated letter too.","The resolution was miscounted; find the shortest word in the complete defining relation (including products of generators).","Resolution is not the number of factors; it is the length of the shortest word."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb349",phase:4,topic:"4.5.3",qtype:"output",difficulty:2,stem:`Minitab shows this table when creating a two-level factorial design:

\`\`\`
Available Factorial Designs (with Resolution)

               Factors
Runs     2     3     4     5     6     7     8
   4  Full   III
   8        Full    IV   III   III   III
  16              Full     V    IV    IV    IV
  32                    Full    VI    IV    IV
  64                          Full   VII     V
 128                                Full  VIII
\`\`\`

A team has **7 factors** for **fibre-network repair time** and needs **at least Resolution V**. What is the smallest number of runs?`,options:["16 runs (Resolution IV)","32 runs (Resolution IV)","64 runs (Resolution VII)","128 runs (Full)"],answer:2,hint:"Read down the factor column to the first run size whose resolution meets the requirement.",steps:[{title:"Find the column",body:"7 factors: 8 → III, 16 → IV, 32 → IV, 64 → VII, 128 → Full."},{title:"Apply the requirement",body:"The first entry at or above V is 64 runs (VII)."},{title:"Trade-off",body:"If 64 runs are too many, consider whether all 7 factors are needed, or accept Resolution IV and use process knowledge for the aliased 2FIs."}],final:"64 runs → answer **C**",whyWrong:["Resolution IV aliases two-factor interactions with each other; the team needs at least V.","With 7 factors, 32 runs still give only Resolution IV.","","A full factorial works but is not the smallest option meeting Resolution V."],bookRef:"Syllabus 4.5.3"},{id:"sv-4-bb350",phase:4,topic:"4.5.3",qtype:"output",difficulty:2,stem:`Using the same Minitab table:

\`\`\`
Available Factorial Designs (with Resolution)

               Factors
Runs     2     3     4     5     6     7     8
   4  Full   III
   8        Full    IV   III   III   III
  16              Full     V    IV    IV    IV
  32                    Full    VI    IV    IV
  64                          Full   VII     V
 128                                Full  VIII
\`\`\`

A team has **8 factors** for **IVR containment rate** and wants **main effects clear of two-factor interactions** with the fewest runs. Which design should it choose?`,options:["8 runs, Resolution III","16 runs, Resolution IV","64 runs, Resolution V","32 runs, Resolution IV"],answer:1,hint:"Main effects clear of 2FIs ⇔ Resolution ≥ IV.",steps:[{title:"Requirement",body:"Resolution IV or higher."},{title:"Read the 8-factor column",body:"16 → IV, 32 → IV, 64 → V, 128 → VIII."},{title:"Decide",body:"The 16-run $2^{8-4}_{IV}$ is the smallest that meets the requirement."}],final:"16 runs, Res IV → answer **B**",whyWrong:["8 runs cannot hold 8 factors (only 7 columns), and Resolution III would alias main effects with 2FIs anyway.","","Resolution V is more than needed; Resolution IV already keeps main effects clear of 2FIs.","This meets the requirement but uses more runs than the 16-run Resolution IV design."],bookRef:"Syllabus 4.5.3"}];export{e as items};
